export const defaults={setup:'A',risk:100,maxContracts:3,dailyLoss:300,commission:1.24,slipTicks:1,stopBuffer:1,minGap:1,displacement:8,rr:2,requireContext:true,requireLiquidity:false,levels:'',sessionStart:'09:30',sessionEnd:'11:30'};
const ny=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
export function clock(t){const p=Object.fromEntries(ny.formatToParts(new Date(t)).map(x=>[x.type,x.value]));return {day:`${p.year}-${p.month}-${p.day}`,hm:p.hour+':'+p.minute};}
export function csvParse(text){let rows=[],row=[],v='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(!quoted&&(c===','||c==='\n'||c==='\r')){row.push(v.trim());v='';if(c!==','){if(row.some(Boolean))rows.push(row);row=[];if(c==='\r'&&text[i+1]==='\n')i++;}}else v+=c;}if(quoted)throw Error('Unclosed CSV quote.');if(v||row.length){row.push(v.trim());rows.push(row);}return rows;}
export function parseCandles(text){const rows=csvParse(text);if(rows.length<21)throw Error('Import at least 20 one-minute candles.');const h=rows.shift().map(x=>x.toLowerCase().replace(/^\ufeff/,''));const fields=['timestamp','open','high','low','close'];const ids=fields.map(f=>h.indexOf(f));if(ids.some(i=>i<0))throw Error('CSV needs timestamp,open,high,low,close headers.');if(rows.length>200000)throw Error('Please import at most 200,000 rows at a time.');let last=-Infinity;return rows.map((r,i)=>{let raw=r[ids[0]],t;if(/^\d{10}$/.test(raw))t=Number(raw)*1000;else if(/^\d{13}$/.test(raw))t=Number(raw);else {if(!/(Z|[+-]\d\d:\d\d)$/i.test(raw))throw Error(`Row ${i+2}: timestamp needs Z or a UTC offset.`);t=Date.parse(raw);}const [o,high,low,c]=ids.slice(1).map(j=>r[j]===''?NaN:Number(r[j]));if(!Number.isFinite(t)||t%60000||![o,high,low,c].every(Number.isFinite)||low<=0||high<Math.max(o,c,low)||low>Math.min(o,c)||t<=last)throw Error(`Row ${i+2}: check prices, minute alignment, duplicates, and ascending timestamps.`);last=t;return {t,o,h:high,l:low,c};});}
export function aggregate(bars,minutes){const out=[];let group=[];for(const b of bars){if(group.length&&(Math.floor(b.t/(minutes*60000))!==Math.floor(group[0].t/(minutes*60000)))){if(group.length===minutes&&group[0].t%(minutes*60000)===0&&group.at(-1).t-group[0].t===(minutes-1)*60000)out.push({t:group[0].t,end:group.at(-1).t+60000,o:group[0].o,h:Math.max(...group.map(b=>b.h)),l:Math.min(...group.map(b=>b.l)),c:group.at(-1).c});group=[];}group.push(b);}if(group.length===minutes&&group[0].t%(minutes*60000)===0&&group.at(-1).t-group[0].t===(minutes-1)*60000)out.push({t:group[0].t,end:group.at(-1).t+60000,o:group[0].o,h:Math.max(...group.map(b=>b.h)),l:Math.min(...group.map(b=>b.l)),c:group.at(-1).c});return out;}
const ceilTick=x=>Math.ceil(x*4-1e-8)/4;
const floorTick=x=>Math.floor(x*4+1e-8)/4;
export function validateConfig(c){for(const k of ['risk','maxContracts','dailyLoss','rr','displacement','minGap'])if(!Number.isFinite(+c[k])||+c[k]<=0)throw Error(k+' must be positive.');for(const k of ['commission','slipTicks','stopBuffer'])if(!Number.isFinite(+c[k])||+c[k]<0)throw Error(k+' must be nonnegative.');if(!Number.isInteger(+c.maxContracts)||!Number.isInteger(+c.slipTicks))throw Error('Contracts and slippage ticks must be whole numbers.');if(!/^\d\d:\d\d$/.test(c.sessionStart)||!/^\d\d:\d\d$/.test(c.sessionEnd)||c.sessionStart>=c.sessionEnd||c.sessionEnd>'16:00')throw Error('Use a valid entry window ending by 16:00 New York.');const levels=c.levels.trim()?c.levels.split(',').map(Number):[];if(levels.some(x=>!Number.isFinite(x)||x<=0))throw Error('Liquidity levels must be positive numbers separated by commas.');return levels;}
export function research(bars,input={}){const cfg={...defaults,...input};const levels=validateConfig(cfg),fives=aggregate(bars,5),fifteens=aggregate(bars,15);let p5=0,p15=0,g15=[],g5=[],g1=[],touch=-Infinity,trades=[],signals=[],position=null,pending=null,day='',dayPnl=0,dayLocked=false,equity=0,peak=0,maxDrawdown=0;const slip=cfg.slipTicks*.25;
function close(b,exit,reason){const gross=(position.entry-exit)*2*position.qty,pnl=gross-cfg.commission*position.qty;const t={...position,exit,exitTime:b.t,pnl,gross,reason};delete t.barIndex;trades.push(t);equity+=pnl;dayPnl+=pnl;peak=Math.max(peak,equity);maxDrawdown=Math.max(maxDrawdown,peak-equity);if(dayPnl<=-cfg.dailyLoss)dayLocked=true;position=null;}
for(let i=0;i<bars.length;i++){const b=bars[i],time=clock(b.t),end=b.t+60000;if(time.day!==day){if(position)close(b,b.o+slip,'Session boundary');day=time.day;dayPnl=0;dayLocked=false;pending=null;g1=[];g5=[];g15=[];touch=-Infinity;}
if(position){if(time.hm>='16:00')close(b,b.o+slip,'Session close');else if(b.h>=position.stop)close(b,Math.max(b.o,position.stop)+slip,'Stop');else if(b.l<=position.target)close(b,position.target,'Target');}
if(pending){const sig=pending;pending=null;if(!position&&!dayLocked&&time.hm>=cfg.sessionStart&&time.hm<cfg.sessionEnd&&b.t===sig.t+60000){const entry=floorTick(b.o-slip),stop=ceilTick(sig.swing+cfg.stopBuffer),distance=stop-entry;const below=levels.filter(v=>v<entry).sort((a,b)=>b-a);const target=below.length?ceilTick(below[0]):ceilTick(entry-distance*cfg.rr);const reward=entry-target,rr=reward/distance;const unitRisk=(distance+slip)*2+cfg.commission;const budget=Math.min(cfg.risk,Math.max(0,cfg.dailyLoss+dayPnl));const qty=Math.min(cfg.maxContracts,Math.floor(budget/unitRisk));const liquidity=below.length>0;sig.entry=entry;sig.stop=stop;sig.target=target;sig.rr=rr;sig.qty=qty;sig.liquidity=liquidity;sig.checks.push({label:'Liquidity target supplied',pass:liquidity},{label:`Reward / risk ≥ ${cfg.rr}`,pass:rr>=cfg.rr-1e-8},{label:'Size fits risk limits',pass:qty>=1&&distance>0});sig.grade=sig.setup==='A'&&sig.context&&liquidity&&rr>=cfg.rr-1e-8&&qty>=1&&distance>0?'A++ candidate':'Research candidate';if(distance>0&&reward>0&&qty>=1&&rr>=cfg.rr-1e-8&&(!cfg.requireLiquidity||liquidity)){position={entry,stop,target,qty,entryTime:b.t,setup:sig.setup,grade:sig.grade,signalTime:sig.t,barIndex:i,risk:unitRisk*qty};sig.status='Simulated';if(b.h>=stop)close(b,Math.max(b.o,stop)+slip,'Stop');else if(b.l<=target)close(b,target,'Target');}else sig.status='Filtered';}}
g15=g15.filter(g=>end-g.born<=3600000&&b.c<=g.hi);for(const g of g15)if(b.h>=g.lo&&b.l<=g.hi)touch=end;
while(p15<fifteens.length&&fifteens[p15].end<=end){const k=p15++,c=fifteens[k],a=fifteens[k-2];if(a&&c.t-a.t===30*60000&&a.l-c.h>=cfg.minGap)g15.push({lo:c.h,hi:a.l,born:c.end});}
let candidate=null;
while(p5<fives.length&&fives[p5].end<=end){const k=p5++,c=fives[k],a=fives[k-2];for(const g of g5){if(c.c<g.lo&&c.end>g.born){if(!g.used){candidate={setup:'A',context:c.end-touch<=3600000,gap:{...g},swing:Math.max(...bars.slice(Math.max(0,i-4),i+1).map(x=>x.h))};g.used=true;}}}g5=g5.filter(g=>!g.used&&c.end-g.born<=3600000);if(a&&c.t-a.t===10*60000&&c.l-a.h>=cfg.minGap)g5.push({lo:a.h,hi:c.l,born:c.end,used:false});}
g1=g1.filter(g=>end-g.born<=1800000&&b.c<=g.hi);if(cfg.setup==='B'){for(const g of g1)if(end>g.born&&b.h>=g.lo&&b.l<=g.hi&&b.c<b.o){candidate={setup:'B',context:false,gap:g,swing:Math.max(...bars.slice(Math.max(0,i-4),i+1).map(x=>x.h))};g.used=true;break;}g1=g1.filter(g=>!g.used);}
if(i>=2&&b.t-bars[i-2].t===120000&&bars[i-2].l-b.h>=cfg.minGap&&bars[i-1].o-bars[i-1].c>=cfg.displacement)g1.push({lo:b.h,hi:bars[i-2].l,born:end});
if(candidate&&candidate.setup===cfg.setup&&!position&&!pending&&!dayLocked&&time.hm>=cfg.sessionStart&&time.hm<cfg.sessionEnd){const s={...candidate,t:b.t,status:'Filtered',grade:'Research candidate',checks:[{label:'Completed candle signal',pass:true},{label:cfg.setup==='A'?'Five-minute gap inversion':'One-minute bearish gap retest',pass:true},{label:'15-minute bearish gap context',pass:candidate.context}],liquidity:false};signals.push(s);if(!cfg.requireContext||s.context||cfg.setup==='B'){pending=s;s.status='Await next candle';}else s.status='Missing context';}
}
if(position)close(bars.at(-1),bars.at(-1).c+slip,'End of dataset');const wins=trades.filter(t=>t.pnl>0),profit=wins.reduce((s,t)=>s+t.pnl,0),loss=-trades.filter(t=>t.pnl<0).reduce((s,t)=>s+t.pnl,0);return {trades,signals,net:equity,winRate:trades.length?wins.length/trades.length*100:0,profitFactor:loss?profit/loss:null,maxDrawdown,bars:bars.length,cfg};}
export function demoCandles(){let x=84219;const rng=()=>{x=(1664525*x+1013904223)>>>0;return x/4294967296;};let bars=[],price=22000;for(let d=0;d<5;d++){const t=Date.UTC(2026,0,5+d,14,30);for(let i=0;i<390;i++){const cycle=i%90;let drift=cycle<24?-.8:cycle<43?1.3:cycle<54?-3:cycle<70?.8:-.4;const o=price,c=Math.round((o+drift+(rng()-.5)*10)*4)/4,h=Math.ceil((Math.max(o,c)+rng()*3)*4)/4,l=Math.floor((Math.min(o,c)-rng()*3)*4)/4;bars.push({t:t+i*60000,o,h,l,c});price=c;}price+=30;}return bars;}
